14	public class BuildOwner {
15	
16	    public void service(@RequestBody OwnerFieldsDto request, OwnerMapper ownerMapper, Out<Owner> built)
17	            throws MissingOwnerFieldsException {
18	        List<String> missing = new ArrayList<>();
19	        require("firstName", request.getFirstName(), missing);
20	        require("lastName", request.getLastName(), missing);
21	        if (isBlank(request.getAddressLine1()) && isBlank(request.getAddress())) {
22	            missing.add("address"); // an address in either form is required
23	        }
24	        require("city", request.getCity(), missing);
25	        require("telephone", request.getTelephone(), missing);
26	        if (!missing.isEmpty()) {
27	            throw new MissingOwnerFieldsException(missing);
28	        }
29	        Owner owner = ownerMapper.toOwner(request);
30	        LocalDate effective = owner.getRegistrationDate() == null ? LocalDate.now() : owner.getRegistrationDate();
31	        owner.setRegistrationDate(BusinessDay.nextBusinessDay(effective));
32	        built.set(owner);
33	    }
34	
35	    private static void require(String field, String value, List<String> missing) {
36	        if (isBlank(value)) {
37	            missing.add(field);
38	        }
39	    }
40	
41	    private static boolean isBlank(String value) {
42	        return value == null || value.isBlank();
43	    }
44	}
