11	/**
12	 * Rewrites the built owner's address into a canonical form in place, so later steps save, compare
13	 * (household duplicate detection and the shared household id) and return it as {@code address}. The
14	 * value is trimmed, its internal whitespace collapsed, upper-cased and common street-type
15	 * abbreviations expanded (ST->STREET, RD->ROAD, AVE->AVENUE). An address that is blank after
16	 * normalization is rejected 400 via {@link MissingOwnerFieldsException}.
17	 */
18	public class NormalizeOwnerAddress {
19	
20	    private static final Map<String, String> ABBREVIATIONS = Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
21	
22	    public void service(@Val Owner owner) throws MissingOwnerFieldsException {
23	        String line1 = normalize(owner.getAddressLine1());
24	        if (!line1.isEmpty()) {
25	            String line2 = normalize(owner.getAddressLine2());
26	            owner.setAddressLine1(line1);
27	            owner.setAddressLine2(line2.isEmpty() ? null : line2);
28	            owner.setAddress(line2.isEmpty() ? line1 : line1 + ' ' + line2);
29	            return;
30	        }
31	        String address = normalize(owner.getAddress());
32	        if (address.isEmpty()) {
33	            throw new MissingOwnerFieldsException(List.of("address"));
34	        }
35	        owner.setAddress(address);
36	    }
37	
38	    private static String normalize(String value) {
39	        String trimmed = value == null ? "" : value.trim();
40	        if (trimmed.isEmpty()) {
41	            return "";
42	        }
43	        StringBuilder normalized = new StringBuilder();
44	        for (String token : trimmed.split("\\s+")) {
45	            String upper = token.toUpperCase(Locale.ROOT);
46	            if (normalized.length() > 0) {
47	                normalized.append(' ');
48	            }
49	            normalized.append(ABBREVIATIONS.getOrDefault(upper, upper));
50	        }
51	        return normalized.toString();
52	    }
53	}
