10	/**
11	 * Assigns the owner's {@code customerCode} formatted {@code <REGION>-<HASH8>}: REGION is the region
12	 * code derived from the postcode (see {@link Locality}), and HASH8 is the first 8 upper-case hex
13	 * characters of SHA-256 over the normalized telephone followed by the last name (e.g.
14	 * 'NSW-1A2B3C4D'). Every value derived downstream — the membership number and its check digit, the
15	 * create audit record, and the locality — reads this identity.
16	 */
17	public class AssignOwnerCustomerCode {
18	
19	    public void service(@Val Owner owner) {
20	        owner.setCustomerCode(Locality.of(owner) + "-" + hash8(owner));
21	    }
22	
23	    private static String hash8(Owner owner) {
24	        String key = owner.getTelephone() + owner.getLastName();
25	        try {
26	            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
27	            StringBuilder hash = new StringBuilder(8);
28	            for (int i = 0; i < 4; i++) {
29	                hash.append(String.format("%02X", digest[i]));
30	            }
31	            return hash.toString();
32	        }
33	        catch (NoSuchAlgorithmException ex) {
34	            throw new IllegalStateException(ex);
35	        }
36	    }
37	}
