10	/**
11	 * Ensures the assigned {@code customerCode} is unique. When it collides with an existing owner's
12	 * code, appends {@code -<n>} with the smallest {@code n} of 2 or more that makes it unique.
13	 */
14	public class DeduplicateOwnerCustomerCode {
15	
16	    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
17	        Set<String> taken = new HashSet<>();
18	        for (Owner other : ownerRepository.findAll()) {
19	            if (other != owner) {
20	                taken.add(other.getCustomerCode());
21	            }
22	        }
23	        String code = owner.getCustomerCode();
24	        if (taken.contains(code)) {
25	            int n = 2;
26	            while (taken.contains(code + "-" + n)) {
27	                n++;
28	            }
29	            owner.setCustomerCode(code + "-" + n);
30	        }
31	    }
32	}
