7	/** Rolls a weekend or public-holiday date forward to the next business day; business days
8	 * are returned unchanged. */
9	final class BusinessDay {
10	
11	    /** Fixed public holidays the roll skips. */
12	    private static final Set<LocalDate> HOLIDAYS = Set.of(
13	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
14	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
