20	        DayOfWeek day = date.getDayOfWeek();
21	        while (day == DayOfWeek.SATURDAY || day == DayOfWeek.SUNDAY || HOLIDAYS.contains(date)) {
22	            date = date.plusDays(1);
23	            day = date.getDayOfWeek();
24	        }
25	        return date;
26	    }
27	}
