3	/**
4	 * Maps an owner's {@link MembershipPoints membership points} to a numeric level from 1 to 4:
5	 * 1 for 0-1 points, 2 for 2-3, 3 for 4-5 and 4 for 6 or more.
6	 */
7	public final class MembershipLevel {
8	
9	    private MembershipLevel() {
10	    }
11	
12	    public static int of(int membershipPoints) {
13	        if (membershipPoints >= 6) {
14	            return 4;
15	        }
16	        if (membershipPoints >= 4) {
17	            return 3;
18	        }
19	        if (membershipPoints >= 2) {
20	            return 2;
21	        }
22	        return 1;
23	    }
24	}
