5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.repository.OwnerRepository;
7	
8	/**
9	 * Finds the existing owner this owner is a possible (soft) duplicate of: another owner sharing this
10	 * owner's last name (case-insensitive) and postcode but with a different telephone. A shared last
11	 * name and postcode with a matching telephone would be a hard duplicate (rejected at create, see
12	 * {@link RejectDuplicateOwnerIdentity}), so a differing telephone is exactly the soft-match case.
13	 * Owners without a postcode never soft-match. Returns the matching owner's id (the lowest when
14	 * several match), or {@code null} when there is no possible duplicate.
15	 */
16	public final class PossibleDuplicate {
17	
18	    private PossibleDuplicate() {
19	    }
20	
21	    public static Integer of(Owner owner, OwnerRepository repository) {
22	        if (Boolean.TRUE.equals(owner.getSharesHousehold())) {
23	            return null;
24	        }
25	        String postcode = owner.getPostcode();
26	        if (postcode == null || postcode.isBlank()) {
27	            return null;
28	        }
29	        Integer match = null;
30	        for (Owner other : repository.findAll()) {
31	            if (!Objects.equals(other.getId(), owner.getId()) && postcode.equals(other.getPostcode())
32	                    && equalsIgnoreCase(owner.getLastName(), other.getLastName())
33	                    && !Objects.equals(owner.getTelephone(), other.getTelephone())
34	                    && (match == null || other.getId() < match)) {
35	                match = other.getId();
36	            }
37	        }
38	        return match;
39	    }
40	
41	    private static boolean equalsIgnoreCase(String a, String b) {
42	        return a == null ? b == null : a.equalsIgnoreCase(b);
43	    }
44	}
