7	/**
8	 * Fiscal-year helpers. The fiscal year starts on 1 July and is numbered by the calendar year in
9	 * which it ends, so 1 July 2026 - 30 June 2027 is fiscal year 2027. Values are derived from the
10	 * owner's business-day-adjusted {@code registrationDate}.
11	 */
12	public final class FiscalYear {
13	
14	    private FiscalYear() {
15	    }
16	
17	    /** Fiscal year number for a date (its ending calendar year). */
18	    public static int of(LocalDate date) {
19	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
20	    }
21	
22	    /** The owner's fiscal year formatted {@code FY<YY>}, e.g. {@code FY27}. */
23	    public static String label(Owner owner) {
24	        return String.format("FY%02d", of(owner.getRegistrationDate()) % 100);
25	    }
26	
27	    /** Two-digit fiscal year of the owner's registration, e.g. {@code "27"}. */
28	    public static String yy(Owner owner) {
29	        return String.format("%02d", of(owner.getRegistrationDate()) % 100);
30	    }
31	}
